public static <T> Collector<T, List<List<T>>, List<List<T>>> intoBatches(int size) {
    return Collector.of(
            ArrayList::new, // supplier
            (batches, item) -> { // accumulator
                if (batches.isEmpty() || batches.get(batches.size()-1).size() == size)
                    batches.add(new ArrayList<>(size));
                batches.get(batches.size()-1).add(item);
            },
            (l, r) -> { /* combiner omitted */ return l; },
            b -> b.stream().map(Collections::unmodifiableList).toList()
            // NO IDENTITY_FINISH flag here!
    );
}

